<?php
/**
 * Displays reviewed-outcome rates independently of the operational rejection count.
 *
 * @package RktskyAntispam
 * @since 0.2.0
 * @var array<string,int|float|null> $quality Reviewed confusion counts and fractional rates.
 */

defined( 'ABSPATH' ) || exit;
?>
<section class="rktsky-antispam__quality" aria-labelledby="rktsky-quality-heading">
	<div class="rktsky-antispam__section-title"><h2 id="rktsky-quality-heading"><?php esc_html_e( 'Reviewed detection results', 'wp-antispam' ); ?></h2><span><?php echo esc_html( sprintf( /* translators: 1: reviewed records, 2: unreviewed records. */ __( '%1$d reviewed · %2$d awaiting review', 'wp-antispam' ), (int) $quality['reviewed'], (int) $quality['pending'] ) ); ?></span></div>
	<p class="rktsky-antispam__quality-period"><?php echo esc_html( sprintf( /* translators: %d: number of days in the reviewed dataset. */ __( 'Reviewed entries from the last %d days.', 'wp-antispam' ), (int) $quality['period_days'] ) ); ?></p>
	<p class="rktsky-antispam__quality-privacy"><?php esc_html_e( 'Feedback uses local, linkable HMAC case references for up to 90 days, also in privacy-conscious mode. Scheduled cleanup may run late.', 'wp-antispam' ); ?> <a href="<?php echo esc_url( admin_url( 'erase-personal-data.php' ) ); ?>"><?php esc_html_e( 'WordPress privacy tools', 'wp-antispam' ); ?> →</a></p>
	<div class="rktsky-antispam__metrics">
		<div class="rktsky-antispam__metric"><span><?php esc_html_e( 'Precision', 'wp-antispam' ); ?></span><strong><?php echo esc_html( null === $quality['precision'] ? '—' : number_format_i18n( 100 * $quality['precision'], 1 ) . '%' ); ?></strong><p><?php esc_html_e( 'Confirmed spam among reviewed rejections.', 'wp-antispam' ); ?></p></div>
		<div class="rktsky-antispam__metric"><span><?php esc_html_e( 'Recall', 'wp-antispam' ); ?></span><strong><?php echo esc_html( null === $quality['recall'] ? '—' : number_format_i18n( 100 * $quality['recall'], 1 ) . '%' ); ?></strong><p><?php esc_html_e( 'Detected spam among reviewed spam cases.', 'wp-antispam' ); ?></p></div>
		<div class="rktsky-antispam__metric"><span><?php esc_html_e( 'Accuracy', 'wp-antispam' ); ?></span><strong><?php echo esc_html( null === $quality['accuracy'] ? '—' : number_format_i18n( 100 * $quality['accuracy'], 1 ) . '%' ); ?></strong><p><?php esc_html_e( 'Correct decisions among all reviewed cases.', 'wp-antispam' ); ?></p></div>
	</div>
	<details class="rktsky-antispam__details"><summary><?php esc_html_e( 'What is the measurement based on?', 'wp-antispam' ); ?></summary><div class="rktsky-antispam__quality-basis"><p><?php esc_html_e( 'Only reviewed records from the period shown are included. Unreviewed submissions are excluded. These rates describe that reviewed subset and do not establish accuracy across all visitors or forms.', 'wp-antispam' ); ?></p><dl class="rktsky-antispam__reasons"><div><dt><?php esc_html_e( 'Confirmed spam caught', 'wp-antispam' ); ?></dt><dd><?php echo esc_html( number_format_i18n( (int) $quality['tp'] ) ); ?></dd></div><div><dt><?php esc_html_e( 'False alarms', 'wp-antispam' ); ?></dt><dd><?php echo esc_html( number_format_i18n( (int) $quality['fp'] ) ); ?></dd></div><div><dt><?php esc_html_e( 'Missed spam', 'wp-antispam' ); ?></dt><dd><?php echo esc_html( number_format_i18n( (int) $quality['fn'] ) ); ?></dd></div><div><dt><?php esc_html_e( 'Confirmed normal', 'wp-antispam' ); ?></dt><dd><?php echo esc_html( number_format_i18n( (int) $quality['tn'] ) ); ?></dd></div></dl><p><?php esc_html_e( 'Review quarantined submissions and use supported native comment or form moderation to improve the dataset. A dash means no reviewed basis is available for that rate.', 'wp-antispam' ); ?></p></div></details>
	<details class="rktsky-antispam__details"><summary><?php esc_html_e( 'Classify a delivered submission', 'wp-antispam' ); ?></summary><form action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>" method="post" class="rktsky-antispam__quality-basis rktsky-antispam__delivered-report"><input type="hidden" name="action" value="rktsky_antispam_classify_delivered" /><?php wp_nonce_field( 'rktsky_antispam_classify_delivered' ); ?><p><?php esc_html_e( 'Use this for submissions that reached your inbox or entries list. Review quarantined submissions in Quarantine.', 'wp-antispam' ); ?></p><div class="rktsky-antispam__report-fields"><div class="rktsky-antispam__field"><label for="rktsky-delivered-provider"><?php esc_html_e( 'Integration', 'wp-antispam' ); ?></label><select id="rktsky-delivered-provider" name="provider"><?php foreach ( \Rktsky\Antispam\Providers::labels() as $rktsky_antispam_provider => $rktsky_antispam_label ) : ?><option value="<?php echo esc_attr( $rktsky_antispam_provider ); ?>"><?php echo esc_html( $rktsky_antispam_label ); ?></option><?php endforeach; ?></select></div><div class="rktsky-antispam__field"><label for="rktsky-delivered-reference"><?php esc_html_e( 'Stable case reference', 'wp-antispam' ); ?></label><input type="text" id="rktsky-delivered-reference" name="reference" maxlength="128" required aria-describedby="rktsky-delivered-help" autocomplete="off" /></div><div class="rktsky-antispam__field"><label for="rktsky-delivered-assessment"><?php esc_html_e( 'Actions', 'wp-antispam' ); ?></label><select id="rktsky-delivered-assessment" name="assessment" required><option value=""><?php esc_html_e( 'Choose an action', 'wp-antispam' ); ?></option><option value="spam"><?php esc_html_e( 'Spam', 'wp-antispam' ); ?></option><option value="normal"><?php esc_html_e( 'Not spam', 'wp-antispam' ); ?></option><option value="forget"><?php esc_html_e( 'Forget case reference', 'wp-antispam' ); ?></option></select></div></div><p class="description" id="rktsky-delivered-help"><?php esc_html_e( 'Use an existing native entry ID or a stable internal case reference without personal content. Forgetting removes the link; reviewed counts keep their evaluation window. Provider entries remain in place.', 'wp-antispam' ); ?></p><button type="submit" class="button"><?php esc_html_e( 'Apply case action', 'wp-antispam' ); ?></button></form></details>
</section>
